/**
 * Faculty semester-at-a-glance calendar (18-week Sun–Sat, Master Calendar layout).
 */

import { escapeHtml } from '../dialogs.js';
import { getFileRoot } from '../../core/state.js';
import { listAllSlots } from '../../core/faculty-schedule/slot-inventory.js';
import {
  listProgramSlots,
  listProgramMyAssignedSlots,
  listAllSubstitutes
} from '../../core/faculty-schedule/program-inventory.js';
import { listMyAssignedSlots } from '../../proposals/substitute-proposals.js';
import {
  groupSlots,
  compressedChipHtml,
  slotChipHtml,
  kindLabel
} from './chips.js';
import { formatHhmmDisplay } from '../../core/schedule-hours.js';
import { weekGridHtml } from './week-grid.js';

function esc(s) {
  return escapeHtml(s == null ? '' : String(s));
}

function shortName(fullName) {
  var parts = String(fullName || '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return '';
  if (parts.length === 1) return parts[0];
  return parts[0].charAt(0).toUpperCase() + '. ' + parts[parts.length - 1];
}

function glanceEventsForUser(semester, session, fileRoot) {
  fileRoot = fileRoot || getFileRoot();
  var assigned;
  var subs;
  if (fileRoot && Array.isArray(fileRoot.semesters) && fileRoot.semesters.length) {
    assigned = session
      ? listProgramMyAssignedSlots(fileRoot, session)
      : listProgramSlots(fileRoot).filter(function (s) { return !s.open; });
    subs = listAllSubstitutes(fileRoot);
  } else {
    assigned = session
      ? listMyAssignedSlots(semester, session)
      : listAllSlots(semester).filter(function (s) { return !s.open; });
    subs = (semester.facultySchedule && semester.facultySchedule.substitutes) || [];
  }
  var events = [];
  assigned.forEach(function (slot) {
    (slot.instances || []).forEach(function (inst) {
      var cover = subs.find(function (s) {
        return s.slotId === slot.slotId && s.date === inst.date;
      });
      events.push({
        date: inst.date,
        weekIndex: inst.weekIndex,
        weekday: inst.weekday || '',
        slot: slot,
        substitute: cover || null
      });
    });
  });
  return events;
}

function glanceDayHtml(ctx, subByDateSlot, expandedMap) {
  var groups = groupSlots(ctx.slots);
  var html = '';
  groups.forEach(function (group) {
    var expandKey = ctx.date + '|' + group.key;
    var expanded = !!(expandedMap && expandedMap[expandKey]);
    if (!expanded) {
      html += compressedChipHtml(group, { date: ctx.date, expanded: false });
      return;
    }
    html += '<div class="faculty-chip-group-expanded" data-faculty-group="' +
      esc(group.key) + '" data-date="' + esc(ctx.date) + '">';
    group.slots.forEach(function (slot) {
      html += slotChipHtml(slot, {});
      var cover = subByDateSlot[ctx.date + '|' + slot.slotId];
      if (cover) {
        html += '<div class="faculty-sub-marker">Sub: ' +
          esc(shortName(cover.coveringName)) +
          ' (' + esc(formatHhmmDisplay(cover.timeStart)) + '-' +
          esc(formatHhmmDisplay(cover.timeEnd)) + ')</div>';
      }
    });
    html += '</div>';
  });
  return html;
}

function glanceHtml(semester, session, expandedGroups, fileRoot) {
  expandedGroups = expandedGroups || {};
  var events = glanceEventsForUser(semester, session, fileRoot);
  var byDate = {};
  var subByDateSlot = {};

  events.forEach(function (ev) {
    if (!ev.date || !ev.slot) return;
    if (!byDate[ev.date]) byDate[ev.date] = [];
    var already = byDate[ev.date].some(function (s) {
      return s.slotId === ev.slot.slotId;
    });
    if (!already) byDate[ev.date].push(ev.slot);
    if (ev.substitute) {
      subByDateSlot[ev.date + '|' + ev.slot.slotId] = ev.substitute;
    }
  });

  var grid = weekGridHtml(semester, byDate, function (ctx) {
    return glanceDayHtml(ctx, subByDateSlot, expandedGroups);
  });

  return '<div id="facultyGlancePanel" class="faculty-glance">' +
    '<div class="faculty-glance-toolbar">' +
    '<button type="button" class="btn btn-sm" id="facultyExportIcsBtn">Export ICS</button> ' +
    '<button type="button" class="btn btn-sm" id="facultyExportPdfBtn">Export PDF</button>' +
    '</div>' +
    '<section class="card faculty-browse-card" style="padding:1.25rem">' +
    '<p class="section-sub" style="margin-top:0">Sun–Sat week grid — your assigned faculty schedule.</p>' +
    grid +
    '</section></div>';
}

export {
  glanceHtml,
  glanceEventsForUser,
  shortName,
  kindLabel
};
